891	export const makeCharRule = (
892	  ruleDef: InternalRuleDefChar | InternalRuleDefCharNot,
893	): RuleChar | RuleCharExclude => {
894	  const value = ruleDef.value as (number | Range)[];
895	  if (isRuleDefCharNot(ruleDef)) {
896	    return ruleCharExclude(value);
897	  }
898	  if (isRuleDefChar(ruleDef)) {
899	    return ruleChar(value);
900	  }
901	
902	  throw new Error(
903	    `Unsupported rule type for make_char_rule: ${JSON.stringify(ruleDef)}`,
904	  );
905	};
