907	export const buildRuleStack = (
908	  linearRules: InternalRuleDef[],
909	): UnresolvedRule[][] => {
910	  let paths: UnresolvedRule[] = [];
911	  const stack: UnresolvedRule[][] = [];
912	  let idx = 0;
913	
914	  while (idx < linearRules.length) {
915	    const ruleDef = linearRules[idx];
916	    if (isRuleDefChar(ruleDef) || isRuleDefCharNot(ruleDef)) {
917	      // this could be a single char, or a range, or a sequence of alts; we don't know until we step through it.
918	      const charRule = makeCharRule(ruleDef);
919	      idx += 1;
920	      let rule: InternalRuleDef | undefined = linearRules[idx];
921	      while (
922	        idx < linearRules.length &&
923	        (isRuleDefCharRngUpper(rule) || isRuleDefCharAlt(rule))
924	      ) {
925	        if (isRuleDefCharRngUpper(rule)) {
926	          // previous rule value should be a number
927	          const prevValue = charRule.value.pop();
928	          if (isRange(prevValue)) {
929	            throw new Error(
930	              `Unexpected range, expected a number but got an array: ${JSON.stringify(prevValue)}`,
931	            );
932	          }
933	          if (prevValue === undefined) {
934	            throw new Error('Unexpected undefined value');
935	          }
936	
937	          charRule.value.push([prevValue, rule.value]);
938	        }
939	        if (isRuleDefCharAlt(rule)) {
940	          charRule.value.push(rule.value);
941	        }
942	        idx += 1;
943	        rule = linearRules[idx];
944	      }
945	      paths.push(charRule);
946	    } else {
947	      if (isRuleDefAlt(ruleDef)) {
948	        if (paths.length === 0) {
949	          throw new Error('Encountered alt without anything before it');
950	        }
951	        paths.push(ruleEnd());
952	        stack.push(paths);
953	        paths = [];
954	      } else if (isRuleDefEnd(ruleDef)) {
955	        paths.push(ruleEnd());
956	      } else if (isRuleDefRef(ruleDef)) {
957	        paths.push(new RuleRef(ruleDef.value));
958	      } else if (isRuleDefCharAlt(ruleDef)) {
959	        throw new Error(
960	          `Encountered char alt, should be handled by above block: ${JSON.stringify(ruleDef)}`,
961	        );
962	      } else {
963	        throw new Error(`Unsupported rule type: ${JSON.stringify(ruleDef)}`);
964	      }
965	      idx += 1;
966	    }
967	  }
968	
969	  if (!isRuleEnd(paths[paths.length - 1])) {
970	    paths.push(ruleEnd());
971	  }
972	
973	  stack.push(paths);
974	  return stack;
975	};
