1006	const ESCAPE_SEQUENCES: Record<string, number> = {
1007	  t: 9,
1008	  r: 13,
1009	  n: 10,
1010	};
1011	
1012	const LITERAL_ESCAPES = ['"', '[', ']', '\\'];
1013	
1014	export const parseChar = (src: string, pos: number): [number, number] => {
1015	  if (pos >= src.length) {
1016	    throw new GrammarParseError(
1017	      src,
1018	      pos,
1019	      'Unexpected end of grammar input, failed to complete parse',
1020	    );
1021	  }
1022	
1023	  if (src[pos] === '\\') {
1024	    const next = src[pos + 1];
1025	    if (next === 'x') {
1026	      return [parseInt(src.slice(pos + 2, pos + 4), 16), 4];
1027	    }
1028	    if (next === 'u') {
1029	      return [parseInt(src.slice(pos + 2, pos + 6), 16), 6];
1030	    }
1031	    if (next === 'U') {
1032	      return [parseInt(src.slice(pos + 2, pos + 10), 16), 10];
1033	    }
1034	    if (next in ESCAPE_SEQUENCES) {
1035	      return [ESCAPE_SEQUENCES[next], 2];
1036	    }
1037	    if (LITERAL_ESCAPES.includes(next)) {
1038	      return [next.charCodeAt(0), 2];
1039	    }
1040	    throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
1041	  }
1042	
1043	  const codePoint = src.codePointAt(pos);
1044	  if (codePoint === undefined) {
1045	    throw new GrammarParseError(src, pos, `Unknown character at ${pos}`);
1046	  }
1047	  return [codePoint, 1];
1048	};
