import json, sys
sys.path.insert(0, '/workspace/ported_implementation')
from gbnf import GBNF, Graph, RulesBuilder, build_rule_stack, GrammarParseError, InputParseError

ref = json.load(open('/tmp/ts-dump2.json'))
bad = 0
def check(label, py, ts):
    global bad
    if py != ts:
        bad += 1
        print('MISMATCH', label)
        print('   py:', repr(py))
        print('   ts:', repr(ts))

def ser(rules):
    out = []
    for r in rules:
        d = {'type': r.type.value}
        if hasattr(r, 'value'): d['value'] = r.value
        out.append(d)
    return out

for entry in ref['grammarErrors']:
    g = entry['grammar']
    try:
        s = GBNF(g)
        check(f'grammar {g!r}', {'ok': True, 'rules': ser(s)}, {'ok': entry['ok'], **({'rules': entry.get('rules')} if entry['ok'] else {})} if entry['ok'] else {'ok': False, 'name': entry['name'], 'message': entry['message']})
    except Exception as e:
        name = type(e).__name__
        got = {'ok': False, 'name': name, 'message': str(e)}
        want = {'ok': False, 'name': entry.get('name'), 'message': entry.get('message')} if not entry['ok'] else {'ok': True}
        check(f'grammar {g!r}', got, want)

for fname, data in ref['prints'].items():
    grammar = open(f'/workspace/tests/python/iteration/grammars/{fname}').read()
    b = RulesBuilder(grammar)
    graph = Graph(grammar, [build_rule_stack(r) for r in b.rules], b.symbol_ids.get('root'))
    check(f'print {fname}', graph.print(None, False), data['print'])
    check(f'symbolIds {fname}', [list(x) for x in b.symbol_ids], [list(x) for x in data['symbolIds']])

for c in ref['inputErrors']:
    state = GBNF(c['grammar'], c['initial'])
    try:
        state.add(c['bad'])
        got = {'ok': True}
    except InputParseError as e:
        got = {'ok': False, 'name': type(e).__name__, 'message': str(e), 'mostRecent': e.error_for_most_recent_input, 'src': e.src, 'pos': e.pos}
    want = {k: v for k, v in c.items() if k not in ('grammar', 'initial', 'bad')}
    check(f'input {c["grammar"]!r} {c["initial"]!r}+{c["bad"]!r}', got, want)

print('mismatches:', bad)
EOF
